const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountBatchControls(box,rule,values,changed){
 if(rule.customSizeValue!==undefined){const sync=()=>{for(const key of ['width','height']){const input=box.querySelector(`[data-rf="${key}"]`);if(input)input.closest('fieldset,.field').hidden=values.size!==rule.customSizeValue;}};box.addEventListener('change',sync);sync();}
 if(rule.id==='dtf-transfers'){const note=document.createElement('p');note.className='small';box.firstElementChild.prepend(note);const sync=()=>{note.textContent=values.layout===1?'Upload one print-ready gang sheet. Enter its complete width and height, up to 22 inches wide. Keep transparent space between each design.':'Upload a transparent PNG or SVG. Enter the size of each transfer and the number of copies.';};box.addEventListener('change',sync);sync();}
 if(rule.id.startsWith('ppf-')){const stage=document.createElement('section');stage.className='ppf-selection-preview';stage.innerHTML='<h3>Your protection coverage</h3><svg viewBox="0 0 240 400" role="img" aria-label="Selected PPF panels in green"><path d="M70 15Q120 0 170 15Q196 45 190 320Q186 385 160 392L80 392Q54 385 50 320Q44 45 70 15Z" fill="#e6e9ec" stroke="#5c6673" stroke-width="3"/><path data-panel="hood" d="M65 32Q120 12 175 32L174 110Q120 90 66 110Z"/><path d="M68 117Q120 99 172 117L160 158L80 158Z" fill="#a5bccd"/><rect x="80" y="168" width="80" height="110" rx="15" fill="white"/><path data-panel="mirrors" d="M42 149L70 149L70 162L42 162ZM170 149L198 149L198 162L170 162Z"/><path data-panel="bumper" d="M65 20Q120 2 175 20L175 35Q120 20 65 35Z"/><path data-panel="fenders" d="M52 40L65 40L65 147L52 147ZM175 40L188 40L188 147L175 147Z"/><path data-panel="rockers" d="M52 170L66 170L66 327L52 327ZM174 170L188 170L188 327L174 327Z"/></svg><p data-ppf-caption></p><p class="small">Illustrative panel map; final edges and exclusions are confirmed on your vehicle.</p>';box.firstElementChild.prepend(stage);const sync=()=>{const plan=values.plan;const all=rule.id==='ppf-full';for(const p of stage.querySelectorAll('[data-panel]')){const key=p.dataset.panel,on=all||key==='mirrors'||plan>=1&&['hood','bumper','fenders'].includes(key)||plan===3&&key==='rockers';p.setAttribute('fill',on?'#8bc928':'#e6e9ec');if(key==='hood'&&plan===1&&!all)p.setAttribute('opacity','.55');else p.removeAttribute('opacity');}stage.querySelector('[data-ppf-caption]').textContent=rule.fields.find(f=>f.key==='plan').options.find(o=>o.value===plan)?.label||'';};box.addEventListener('change',sync);sync();}
 if(rule.id==='tint-vehicle'){
  const keys=['glass_fl','glass_fr','glass_rl','glass_rr','glass_back','glass_strip'];
  // exploded ("UV map") view: each window is pulled out of the car top view and linked back to its place
  const P={glass_fl:{x:'M20 214 L104 226 L104 292 L26 304 Z',i:'M124 218 L140 213 L140 282 L124 288 Z',lx:62,ly:262,t:'Front left'},glass_fr:{x:'M340 214 L256 226 L256 292 L334 304 Z',i:'M236 218 L220 213 L220 282 L236 288 Z',lx:298,ly:262,t:'Front right'},glass_rl:{x:'M24 316 L104 306 L104 362 L30 378 Z',i:'M124 296 L140 291 L140 346 L124 354 Z',lx:64,ly:344,t:'Rear left'},glass_rr:{x:'M336 316 L256 306 L256 362 L330 378 Z',i:'M236 296 L220 291 L220 346 L236 354 Z',lx:296,ly:344,t:'Rear right'},glass_back:{x:'M118 452 Q180 464 242 452 L232 494 Q180 506 128 494 Z',i:'M146 372 Q180 380 214 372 L220 398 Q180 408 140 398 Z',lx:180,ly:480,t:'Back glass'},glass_strip:{x:'M112 16 Q180 2 248 16 L244 36 Q180 24 116 36 Z',i:'M142 150 Q180 140 218 150 L216 158 Q180 149 144 158 Z',lx:180,ly:30,t:'Sun strip'}};
  const lbl=k=>esc(rule.fields.find(f=>f.key===k)?.label||P[k].t);
  const h=document.createElement('section');h.className='tint-glass-map';h.innerHTML=`<h3>Select your windows</h3><p>Tap a window — on the car or in the exploded view — to add or remove it. The price updates as you go.</p><svg viewBox="0 0 360 512" aria-label="Vehicle glass selection"><path d="M150 112 Q180 100 210 112 Q238 140 236 250 L236 420 Q233 452 208 458 L152 458 Q127 452 124 420 L124 250 Q122 140 150 112 Z" fill="#eef1f5" stroke="#64748b" stroke-width="3"/><path d="M146 158 Q180 150 214 158 L210 200 Q180 194 150 200 Z" fill="#cfdbe6" stroke="#9aa9b8"/><text x="180" y="186" text-anchor="middle" font-size="9" fill="#64748b">windshield</text><rect x="148" y="206" width="64" height="160" rx="14" fill="#fff" stroke="#d6dde6"/><path d="M118 214 l-10 -4 l0 10 z M242 214 l10 -4 l0 10 z" fill="#64748b"/>${keys.map(k=>{const p=P[k];return `<g role="button" tabindex="0" aria-label="${lbl(k)}" data-glass="${k}"><title>${lbl(k)}</title><path class="ip" d="${p.i}"/><path class="xp" d="${p.x}"/><text x="${p.lx}" y="${p.ly}" text-anchor="middle">${lbl(k).replace('Windshield ','')}</text></g>`;}).join('')}<g class="leaders" stroke="#94a3b8" stroke-dasharray="3 4" fill="none"><path d="M104 258 L124 252"/><path d="M256 258 L236 252"/><path d="M104 336 L124 324"/><path d="M256 336 L236 324"/><path d="M180 452 L180 408"/><path d="M180 36 L180 142"/></g></svg><p data-glass-status role="status"></p>`;box.firstElementChild.prepend(h);
  const checks=[...box.querySelectorAll('.product-check-card')].filter(l=>keys.includes(l.querySelector('input')?.dataset.rf));if(checks.length){const wrap=document.createElement('div');wrap.className='glass-check-grid';checks[0].before(wrap);checks.forEach(c=>wrap.append(c));}
  const sync=()=>{for(const k of keys){const g=h.querySelector(`[data-glass="${k}"]`);if(!g)continue;g.setAttribute('aria-pressed',!!values[k]);g.classList.toggle('on',!!values[k]);const input=box.querySelector(`[data-rf="${k}"]`);if(input)input.checked=!!values[k];}h.querySelector('[data-glass-status]').textContent=keys.filter(k=>values[k]).length+' windows selected';};const toggle=e=>{const g=e.target.closest('[data-glass]');if(!g)return;values[g.dataset.glass]=1-values[g.dataset.glass];sync();changed();};h.onclick=toggle;h.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle(e);}};box.addEventListener('change',sync);sync();
 }
 if(rule.id.startsWith('tint-')){
  const f=rule.fields.find(f=>f.key==='vlt'),input=box.querySelector('[data-rf="vlt"]'),group=input?.closest('fieldset');if(!f||!group)return;
  const preview=document.createElement('section');preview.className='tint-light-preview';preview.innerHTML='<h3>Light transmission</h3><div class="tint-preview-scene'+(rule.id==='tint-vehicle'?' car':' home')+'"><img src="'+(rule.id==='tint-vehicle'?'/satin/img/tint-view-scene.svg':'/satin/img/tint-view-scene.svg')+'" alt="View through tinted glass"><div data-tint-shade></div>'+(rule.id==='tint-vehicle'?'<svg class="tint-frame" viewBox="0 0 1200 700" preserveAspectRatio="none" aria-hidden="true"><path fill-rule="evenodd" fill="#15171b" d="M0 0H1200V700H0Z M150 640 L120 260 Q130 150 260 110 L940 60 Q1080 60 1110 200 L1130 560 Q1130 640 1040 640 Z"/><path d="M0 560 Q300 600 1200 590 L1200 700 L0 700Z" fill="#23262c"/><path d="M60 600 Q140 470 290 470 L330 470 L330 560 Q200 560 110 640 Z" fill="#2b2f36"/><rect x="380" y="610" width="140" height="18" rx="9" fill="#3a3f47"/></svg>':'<svg class="tint-frame" viewBox="0 0 1200 700" preserveAspectRatio="none" aria-hidden="true"><path fill-rule="evenodd" fill="#f3efe8" d="M0 0H1200V700H0Z M140 80H1060V600H140Z"/><path d="M140 80H1060V600H140Z M600 80V600 M140 340H1060" fill="none" stroke="#e2dccf" stroke-width="22"/><rect x="100" y="600" width="1000" height="40" fill="#e7e0d3"/></svg>')+'</div><p data-tint-value></p><p class="small">Visual illustration; screen colours do not represent a measured VLT.</p><p class="tint-legal" data-tint-legal></p>';
  group.after(preview);if(rule.id==='tint-vehicle'){group.innerHTML=`<legend>${esc(f.label)}</legend><input aria-label="Tint shade" type="range" min="0" max="${f.options.length-1}" step="1" value="${f.options.findIndex(o=>o.value===values.vlt)}" data-vlt-slider><div class="vlt-stops">${f.options.map(o=>'<span>'+o.label+'</span>').join('')}</div>`;group.querySelector('input').oninput=e=>{values.vlt=f.options[Number(e.target.value)].value;sync();changed();};}
  function sync(){preview.querySelector('[data-tint-shade]').style.background=`rgba(0,0,0,${1-values.vlt/100})`;preview.querySelector('[data-tint-value]').textContent=values.vlt+'% visible light transmission';const legal=preview.querySelector('[data-tint-legal]');legal.textContent=rule.id==='tint-vehicle'&&values.vlt<70&&(values.glass_fl||values.glass_fr)?'Ontario: front side windows on vehicles manufactured from January 1, 2017 require at least 70% VLT for inspection. This selection is below that level. We will confirm legal placement before installation; an appointment request is not a confirmed booking.':'';}
  box.addEventListener('change',sync);sync();
 }
 if(rule.id.startsWith('design-')&&rule.id!=='design-services'){const sync=()=>{const b=box.querySelector('[data-rule-add]'),q=box.querySelector('[data-quote]');b.hidden=values.purchase===0;q.textContent=values.purchase===0?'Quote price':'Get exact quote';q.dataset.quote='Vehicle Wraps';};box.addEventListener('change',sync);sync();}
 if(rule.id==='wrap-prints'){const p=document.createElement('p');p.className='small';p.textContent=rule.priceNote;box.firstElementChild.prepend(p);const height=box.querySelector('[data-rf="height"]');box.addEventListener('change',()=>{height.max=values.kind===1?48:52;});}
}
